def skill():
    t = Symbol('t')
    x1 = 6*t - t**2
    T = [r for r in solve(x1, t) if r > 0][0]
    G = integrate(2*t**2 - 10*t + 8, t)
    pts = [0, 1, 4, T]
    return sum(abs(G.subs(t, b) - G.subs(t, a)) for a, b in zip(pts[:-1], pts[1:]))

def standard():
    t, s = symbols('t s')
    x1 = integrate(6 - 2*s, (s, 0, t))
    T = [r for r in solve(x1, t) if r > 0][0]
    v2 = 2*t**2 - 10*t + 8
    return integrate(Abs(v2), (t, 0, T))

def unique():
    return [standard()]
